        provider.apiKey = config.apiKey.clone();
        provider.useMultipleApiKeys = config.useMultipleApiKeys;
        provider.apiKeyPool = config.apiKeyPool.iter().map(Operit1ApiKeyInfo::toApiKeyInfo).collect();
